DO $$ DECLARE d text;BEGIN SELECT pg_get_functiondef('public.resolve_join_agency(uuid,uuid,uuid)'::regprocedure) INTO d;d:=replace(d,'AND matched_personnel_id=p_person FOR UPDATE','AND (matched_personnel_id=p_person OR (matched_personnel_id IS NULL AND EXISTS(SELECT 1 FROM personnel pp WHERE pp.id=p_person AND pp.deleted_at IS NULL AND pp.merged_into_id IS NULL AND regexp_replace(COALESCE(pp.phone,''''),''\D'','''',''g'') IN(project_join_requests.phone,''1''||project_join_requests.phone)))) FOR UPDATE');d:=replace(d,'UPDATE personnel SET vendor_id=t.vendor_id','UPDATE project_join_requests SET matched_personnel_id=p_person WHERE id=p_request; UPDATE personnel SET vendor_id=t.vendor_id');EXECUTE d;END $$;